ee:message.ee:set-payload:
%dw 2.0
output application/json
var bodyText = ((payload.Body default payload.body default "") as String)
var lowerBody = lower(bodyText)
fun hasAny(words) = sizeOf(words filter ((word) -> lowerBody contains word)) > 0
var categories = [
    if (hasAny(["wait", "queue", "delay"])) "WAIT_TIME" else null,
    if (hasAny(["room", "clean", "bed"])) "ROOM_READINESS" else null,
    if (hasAny(["bill", "invoice", "refund", "insurance", "payment"])) "BILLING" else null,
    if (hasAny(["pharmacy", "medicine late", "stock", "supply"])) "PHARMACY_STOCK" else null,
    if (hasAny(["lab", "test result"])) "LAB_VENDOR" else null,
    if (hasAny(["food", "meal"])) "FOOD_SERVICE" else null,
    if (hasAny(["rude", "staff"])) "STAFF_INTERACTION" else null,
    if (hasAny(["privacy", "unsafe"])) "PRIVACY_SAFETY" else null,
    if (hasAny(["diagnose", "dosage", "treatment", "triage", "chest pain", "emergency"])) "CLINICAL_REQUEST" else null
] filter ($ != null)
var safeCategories = if (isEmpty(categories)) ["GENERAL_SERVICE"] else categories
var summaryParts = [
    if (safeCategories contains "WAIT_TIME") "waiting time" else null,
    if (safeCategories contains "ROOM_READINESS") "room readiness" else null,
    if (safeCategories contains "BILLING") "billing or payment" else null,
    if (safeCategories contains "PHARMACY_STOCK") "pharmacy or supply" else null,
    if (safeCategories contains "LAB_VENDOR") "lab response" else null,
    if (safeCategories contains "FOOD_SERVICE") "food service" else null,
    if (safeCategories contains "STAFF_INTERACTION") "staff interaction" else null,
    if (safeCategories contains "PRIVACY_SAFETY") "privacy or safety" else null,
    if (safeCategories contains "CLINICAL_REQUEST") "clinical review" else null
] filter ($ != null)
---
{
    tenantKey: p("northstar.tenant"),
    purpose: p("northstar.purpose"),
    messageSid: ((payload.MessageSid default payload.SmsSid default uuid()) as String),
    sourceChannel: "Twilio Sandbox WhatsApp",
    rawBody: bodyText,
    from: ((payload.From default "") as String),
    messageSummary: "A WhatsApp message mentions " ++ (summaryParts joinBy ", ") ++ ".",
    categories: safeCategories,
    clinicalRequest: safeCategories contains "CLINICAL_REQUEST"
}

%dw 2.0
output application/xml
---
{
    Response: {
        Message: "Thanks. North Star received this. A manager will review it."
    }
}

